rows.script:
rule "Crown"
global king: key
global bar: num
global crowned_at: time

on buy {
  let need = fade(bar, over: 6h, since: crowned_at)
  if amount > need {
    set king = buyer
    set bar = amount
    set crowned_at = clock.now
  }
}

on sell {
  refuse if wallet == king and since(crowned_at) < 6h
    because "You're the king: no selling for {6h - since(crowned_at)} unless outbid"
}

rule "Max 2% for the first day"
# No wallet may hold more than 2% of supply during the first 24 hours.
# After 24h the cap lifts and trading is unrestricted.

on buy, send {
  if coin.age < 24h {
    let cap = supply * 2%
    refuse if receiver.balance_after > cap
      because "Max 2% of supply per wallet for the first day. Cap is {cap} tokens"
  }
}

rule "20 buys per minute"
# During the first hour, only 20 buys are allowed per 60-second window.
# The counter resets every minute.

global window_start: time
global buys_in_window: int

on buy {
  if coin.age < 1h {
    let elapsed = since(window_start)
    if elapsed >= 60s or window_start == 0 {
      set window_start = clock.now
      set buys_in_window = 0
    }
    refuse if buys_in_window >= 20
      because "Buy limit reached for this minute. Try again in {60s - since(window_start)}"
    set buys_in_window += 1
  }
}
